static const char PAGE_FOOT[] =
"<p class='footer'>ESP Home Panel \u00b7 Local device settings</p></main><script>'use strict';\n"
"const form=document.getElementById('settings-form');\n"
"if(form){\n"
" const groups=[['network','Network','Connect your panel and give it a name on your network.'],['display','Display','Make the screen, theme, and light presets your own.'],['home-assistant','Home Assistant','Connect your broker and map the devices you control.'],['weather','Weather','Connect your station directly and choose forecast and display units.'],['sensors','Sensors','Bring ambient light and room occupancy into Home Assistant.'],['system','System','Manage administrator access, firmware, and configuration.']];\n"
" const nav=document.getElementById('settings-tabs'),grid=document.getElementById('settings-grid');\n"
" const panels=new Map(),tabs=[];\n"
" for(const [id,title,description] of groups){\n"
"  const button=document.createElement('button');button.type='button';button.id='tab-'+id;button.textContent=title;button.setAttribute('role','tab');button.setAttribute('aria-controls','panel-'+id);nav.append(button);tabs.push(button);\n"
"  const panel=document.createElement('section');panel.id='panel-'+id;panel.className='tab-panel';panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',button.id);panel.tabIndex=0;\n"
"  const heading=document.createElement('div');heading.className='panel-heading';const h=document.createElement('h2');h.textContent=title;const p=document.createElement('p');p.textContent=description;heading.append(h,p);panel.append(heading);\n"
"  const content=document.createElement('div');content.className='grid';grid.querySelectorAll('[data-tab=\"'+id+'\"]').forEach(card=>content.append(card));panel.append(content);grid.before(panel);panels.set(id,panel);\n"
"  button.addEventListener('click',()=>activate(id));\n"
"  button.addEventListener('keydown',event=>{let i=tabs.indexOf(button);if(event.key==='ArrowRight')i=(i+1)%groups.length;else if(event.key==='ArrowLeft')i=(i+groups.length-1)%groups.length;else if(event.key==='Home')i=0;else if(event.key==='End')i=groups.length-1;else return;event.preventDefault();activate(groups[i][0]);tabs[i].focus();});\n"
" }\n"
" function activate(id,remember=true){if(!panels.has(id))id='network';for(const [key,panel] of panels)panel.hidden=key!==id;tabs.forEach((tab,i)=>{const active=groups[i][0]===id;tab.setAttribute('aria-selected',String(active));tab.tabIndex=active?0:-1;});if(remember)history.replaceState(null,'','#'+id);}\n"
" grid.remove();nav.hidden=false;activate(location.hash.slice(1),false);window.addEventListener('hashchange',()=>activate(location.hash.slice(1),false));\n"
" // Labels stay attached when fields are moved between panels.\n"
" form.querySelectorAll('input:not([type=hidden]),select').forEach((input,index)=>{if(!input.id)input.id='setting-'+index;const label=input.previousElementSibling;if(label?.tagName==='LABEL')label.htmlFor=input.id;});\n"
" form.querySelectorAll('input[type=password]').forEach(input=>{const wrap=document.createElement('div');wrap.className='password-wrap';input.before(wrap);wrap.append(input);const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent='Show';button.setAttribute('aria-label','Show '+(input.labels[0]?.textContent||'password'));button.setAttribute('aria-pressed','false');button.addEventListener('click',()=>{const show=input.type==='password';input.type=show?'text':'password';button.textContent=show?'Hide':'Show';button.setAttribute('aria-pressed',String(show));button.setAttribute('aria-label',(show?'Hide ':'Show ')+(input.labels[0]?.textContent||'password'));});wrap.append(button);});\n"
" const range=document.getElementById('backlight'),value=document.getElementById('backlightValue');function backlight(){value.textContent=range.value+'%';}range.addEventListener('input',backlight);backlight();\n"
" const fields=Array.from(form.elements).filter(el=>el.name&&el.type!=='hidden');\n"
" const snapshot=()=>JSON.stringify(fields.map(el=>[el.name,el.type==='checkbox'?el.checked:el.value]));\n"
" function topics(){document.getElementById('topic-preview').value=form.elements.mqtt_base_topic.value.replace(/\\/+$/,'')+'/'+form.elements.panel_id.value;document.getElementById('discovery-preview').value=form.elements.mqtt_discovery_prefix.value.replace(/\\/+$/,'')+'/status';}form.addEventListener('input',topics);topics();\n"
" function weatherFields(){\n"
"  const f=form.elements,enabled=f.weather_enabled.value==='1',ambient=f.weather_provider.value==='1',wu=f.weather_forecast.value==='1',off=f.weather_forecast.value==='2';\n"
"  for(const id of ['weather-station-settings','weather-forecast-settings','weather-display-settings'])document.getElementById(id).disabled=!enabled;\n"
"  function reveal(id,visible){const box=document.getElementById(id);box.hidden=!visible;box.disabled=!visible;}\n"
"  reveal('weather-ambient-key',ambient);reveal('weather-wu-key',wu);\n"
"  document.getElementById('weather-station-label').textContent=ambient?'Ambient station name or MAC address':'Weather Underground station ID';\n"
"  f.weather_station.placeholder=ambient?'Backyard or AA:BB:CC:DD:EE:FF':'KGAEVANS123';\n"
"  document.getElementById('weather-station-help').textContent=ambient?'Use the station name from AmbientWeather.net. If names are duplicated, use its MAC address.':'Use the PWS station ID from My Devices, not the station display name or upload password.';\n"
"  document.getElementById('weather-api-label').textContent=(ambient?'Ambient Weather':'Weather Underground')+' API key';\n"
"  document.getElementById('weather-forecast-key-label').textContent=ambient?'Weather Underground forecast API key':'Separate forecast API key (optional)';\n"
"  document.getElementById('weather-forecast-help').textContent=off?'Only station observations will be shown. Forecast cards and sunrise/sunset will be unavailable.':wu?(ambient?'Enter a Weather Underground key with daily forecast access. Your Ambient keys cannot be used for forecasts.':'Your station API key will be used unless you provide a separate forecast key. The key must include daily forecast access.')+' Weather Underground provides daily cards; choose Open-Meteo for the hourly chart.':'No extra account or key needed. Open-Meteo provides the 12-hour chart and five-day forecast at your station location.';\n"
"  document.getElementById('weather-summary').textContent=enabled?(ambient?'Ambient Weather':'Weather Underground')+' observations'+(off?' \u00b7 Forecast off':wu?' \u00b7 Weather Underground daily forecast':' \u00b7 Open-Meteo hourly and daily forecast'):'Weather is off. Turn it on to configure your station and forecasts.';\n"
"  f.weather_station.required=enabled;\n"
"  for(const [name,needed] of [['weather_api_key',enabled],['weather_app_key',enabled&&ambient],['weather_forecast_key',enabled&&wu&&ambient]]){\n"
"   const input=f[name],clear=f['clear_'+name],sameProvider=name!=='weather_api_key'||input.dataset.provider===f.weather_provider.value;\n"
"   const saved=input.dataset.saved==='1'&&sameProvider;\n"
"   input.required=needed&&!saved;\n"
"   input.setCustomValidity(needed&&clear.checked?'Uncheck Clear saved key to use this required credential.':'');\n"
"   input.placeholder=saved?'Saved \u2014 leave blank to keep':name==='weather_forecast_key'&&!ambient?'Leave blank to use the station API key':'Enter '+(name==='weather_app_key'?'application key':'API key');\n"
"  }\n"
" }\n"
" form.addEventListener('change',weatherFields);weatherFields();\n"
" const initial=snapshot();let dirty=false,saving=false,saved=false;\n"
" const save=document.getElementById('save-settings'),discard=document.getElementById('discard-settings'),notice=document.getElementById('save-notice');\n"
" function update(){dirty=!saved&&snapshot()!==initial;save.disabled=saving||saved||!dirty;discard.disabled=saving||saved||!dirty;document.getElementById('change-status').textContent=saved?'Settings saved':dirty?'Unsaved changes':'All changes saved';}\n"
" form.addEventListener('input',update);form.addEventListener('change',update);update();\n"
" discard.addEventListener('click',event=>{event.preventDefault();if(dirty&&!confirm('Discard unsaved changes in all tabs?'))return;form.reset();backlight();topics();weatherFields();notice.hidden=true;update();});\n"
" window.addEventListener('beforeunload',event=>{if(dirty&&!saved){event.preventDefault();event.returnValue='';}});\n"
" form.noValidate=true;\n"
" form.addEventListener('submit',async event=>{\n"
"  event.preventDefault();if(saving||saved)return;const invalid=form.querySelector(':invalid');if(invalid){const panel=invalid.closest('.tab-panel');if(panel)activate(panel.id.slice(6));invalid.focus();invalid.reportValidity();return;}\n"
"  const payload=new URLSearchParams(new FormData(form));saving=true;form.querySelectorAll('input,select').forEach(el=>el.disabled=true);update();save.textContent='Saving\u2026';notice.hidden=false;notice.className='notice';notice.textContent='Saving your settings. The panel will restart.';\n"
"  try{const response=await fetch('/save',{method:'POST',body:payload,credentials:'same-origin',signal:AbortSignal.timeout(20000)});const text=await response.text();if(!response.ok)throw Error(new DOMParser().parseFromString(text,'text/html').body.textContent.trim()||'Could not save settings.');saved=true;dirty=false;notice.textContent='Settings saved. The panel is restarting. If you changed Wi-Fi or the hostname, reconnect using the new network address. ';const link=document.createElement('a');link.href='/'+location.hash;link.textContent='Reconnect to panel';notice.append(link);save.textContent='Saved';form.querySelectorAll('input,select').forEach(el=>el.disabled=true);}catch(error){notice.className='notice error';notice.textContent=error.name==='TimeoutError'?'Could not confirm the save. Reconnect to the panel and check your settings before trying again.':error.message;save.textContent='Save & restart';}finally{saving=false;if(!saved){form.querySelectorAll('input,select').forEach(el=>el.disabled=false);weatherFields();}update();notice.scrollIntoView({block:'nearest',behavior:'smooth'});}\n"
" });\n"
" document.getElementById('reboot-form').addEventListener('submit',event=>{if(saving||saved){event.preventDefault();return;}if(!confirm('Reboot the panel now? Your saved settings will be kept.'+(dirty?' Unsaved changes will be discarded.':''))){event.preventDefault();return;}dirty=false;});\n"
" document.getElementById('reset-form').addEventListener('submit',event=>{if(!confirm('Reset all settings, including Wi-Fi, MQTT, and administrator access, to firmware defaults? The panel will restart.')){event.preventDefault();return;}dirty=false;});\n"
"}\n"
"</script></body></html>"
;
